import { ACTIVITY_STORAGE_NAMES } from './storage-permissions.js';
import { createHash, randomUUID } from 'node:crypto';
import { join, resolve } from 'node:path';
import { getConfigDir } from '../../utils/config.js';
import { ConversationActivityStore } from './store.js';
import { ensureConversationActivityOwner } from './owner-launcher.js';
import { ConversationActivityAttachedService } from './owner-service.js';
import { ConversationActivityOwnerClient } from './owner-client.js';
import { ConversationActivityService } from './service.js';
import { ConversationMcpActivities } from './mcp.js';
const NOTICE_KINDS = new Set(['report', 'artifact_available', 'input_required', 'blocked', 'completed', 'failed', 'cancelled']);
const labels = { accepted: '已接收', queued: '排队中', running: '进行中', blocked: '需要处理', input_required: '等待你的输入', completed: '已完成', failed: '失败', cancelled: '已取消' };
const plain = (value) => value.replace(/\x1b\][^\x07]*(?:\x07|\x1b\\)/g, '').replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '').replace(/[\x00-\x08\x0b-\x1f\x7f]/g, '');
/** Presentation is queued at terminal idle boundaries. The database remains
 * the source of unread/recovery truth, even if no terminal is attached. */
export class CliConversationActivities {
    options;
    store;
    service;
    mcp;
    actor = { requestSource: 'user', actorId: 'cli-user' };
    pending = new Map();
    unsubscribe;
    stopDisconnect;
    refreshPending;
    through = 0;
    disposed = false;
    pendingPresentation = Promise.resolve();
    profileId;
    static async attach(options) {
        const root = join(getConfigDir(), 'conversation-activity', createHash('sha256').update(resolve(options.cwd)).digest('hex').slice(0, 24));
        const profileId = `cli:${createHash('sha256').update(root).digest('hex').slice(0, 24)}`;
        const ownerClient = await ensureConversationActivityOwner({ schemaVersion: 1, dataRoot: root, profileId, actorId: 'cli-user', identity: { kind: 'cli', path: options.identityPath, workspaceRoot: options.cwd } }, { instanceId: options.instanceId, onLegacyOwner: options.onLegacyOwner });
        try {
            return new CliConversationActivities({ ...options, ownerClient, dataRoot: root });
        }
        catch (error) {
            ownerClient.dispose();
            throw error;
        }
    }
    constructor(options) {
        this.options = options;
        const root = options.dataRoot ?? join(options.cwd, '.xiaok', 'state');
        const profileId = `cli:${createHash('sha256').update(root).digest('hex').slice(0, 24)}`;
        this.profileId = profileId;
        this.stopDisconnect = options.ownerClient?.onDisconnect(epoch => {
            void probeReplacementOwner(root, epoch, () => this.disposed).then(replaced => {
                if (replaced && !this.disposed)
                    options.onOwnerReplaced?.();
            });
        });
        this.store = new ConversationActivityStore(join(root, ACTIVITY_STORAGE_NAMES.database), { readOnly: Boolean(options.ownerClient) });
        this.through = this.store.getPresentationCursor(profileId, options.sessionId, 'cli');
        this.service = options.ownerClient ? new ConversationActivityAttachedService(options.ownerClient, this.actor.actorId) : new ConversationActivityService({ store: this.store, profileId, actorId: this.actor.actorId,
            getThread: threadId => threadId === options.sessionId ? { threadId, profileId, workspaceId: root, deleteState: 'none' } : null,
            canObserveWork: watch => this.mcp.canObserve(watch), onError: options.onError });
        this.mcp = new ConversationMcpActivities({ store: this.store, service: this.service, actorId: this.actor.actorId,
            ...(options.ownerClient ? { externalObserver: (connection) => connection.activityEndpoint?.config.type !== 'stdio',
                endpointReady: async (connection) => {
                    const endpoint = connection.activityEndpoint;
                    if (!endpoint || !connection.tasks)
                        throw new Error('activity_mcp_endpoint_unverified');
                    await options.ownerClient.request('mcpRegister', { endpointId: connection.tasks.endpointId, name: endpoint.name,
                        ...(endpoint.config.type !== 'stdio' ? { config: endpoint.config, ...(endpoint.cwd ? { cwd: endpoint.cwd } : {}) } : {}) });
                } } : {}),
            originThread: async (taskId) => taskId === options.sessionId ? options.sessionId : null, onError: options.onError });
        options.platform.setMcpActivityHooks({ connected: connection => this.mcp.register(connection), observer: async (context, connection) => {
                // This context is generated by the runtime; tool JSON cannot supply it.
                if (context.session.sessionId !== options.sessionId && !context.session.lineage.includes(options.sessionId))
                    return;
                return this.mcp.observer(options.sessionId, context.toolInvocationId ?? randomUUID(), connection);
            } });
        void Promise.resolve(this.service.subscribe(options.sessionId, this.actor, () => { void this.refresh().catch(error => options.onError?.(error)); })).then(stop => { if (this.disposed)
            stop();
        else {
            this.unsubscribe = stop;
            void this.refresh().catch(error => options.onError?.(error));
        } }).catch(error => options.onError?.(error));
        this.service.start();
        void this.refresh().catch(error => options.onError?.(error));
    }
    get hasPending() { return this.pending.size > 0; }
    refresh() {
        if (this.refreshPending)
            return this.refreshPending;
        const pending = (async () => {
            if (this.disposed)
                return;
            let after = this.through;
            for (;;) {
                const rows = await this.service.listActivities(this.options.sessionId, this.actor, { afterLocalSeq: after, limit: 200 });
                if (this.disposed)
                    return;
                for (const row of rows) {
                    after = Math.max(after, row.localSeq);
                    if (NOTICE_KINDS.has(row.kind) && this.store.getWatch(row.watchId)?.preference !== 'quiet')
                        this.pending.set(row.watchId, row);
                }
                if (rows.length < 200)
                    break;
            }
            if (this.pending.size)
                this.options.changed();
        })().finally(() => { if (this.refreshPending === pending)
            this.refreshPending = undefined; });
        this.refreshPending = pending;
        return pending;
    }
    flush(canWrite, write) {
        if (!canWrite || this.disposed || !this.pending.size)
            return;
        const rows = [...this.pending.values()].sort((a, b) => a.localSeq - b.localSeq);
        const block = rows.map(row => {
            const status = row.projection.businessOutcome === 'error' ? '失败' : labels[row.projection.executionState];
            return `[异步任务] ${status}${row.projection.summary ? `：${plain(row.projection.summary).slice(0, 1024)}` : ''}`;
        }).join('\n');
        write(`\n${block}\n`);
        this.through = Math.max(this.through, ...rows.map(row => row.localSeq));
        this.pending.clear();
        // Delivery and user read are separate. Quiet rows remain unread; this
        // presentation cursor prevents replaying already painted CLI notices.
        try {
            if (this.options.ownerClient)
                this.pendingPresentation = this.options.ownerClient.request('presented', { threadId: this.options.sessionId, surface: 'cli', through: this.through }).catch(error => this.options.onError?.(error));
            else
                this.store.markPresented(this.profileId, this.options.sessionId, 'cli', this.through);
        }
        catch (error) {
            this.options.onError?.(error);
        }
    }
    async close() { await this.pendingPresentation; this.dispose(); }
    dispose() {
        if (this.disposed)
            return;
        this.disposed = true;
        this.stopDisconnect?.();
        this.unsubscribe?.();
        this.mcp.dispose();
        this.service.dispose();
        this.store.close();
        this.pending.clear();
    }
}
/** A short, read-only attachment provides positive evidence of replacement. */
export async function probeReplacementOwner(dataRoot, disconnectedEpoch, cancelled = () => false) {
    const deadline = Date.now() + 1500;
    while (!cancelled() && Date.now() < deadline) {
        const client = new ConversationActivityOwnerClient(dataRoot, 'producer');
        let timer;
        try {
            const status = await Promise.race([
                client.request('status'),
                new Promise(resolve => { timer = setTimeout(() => resolve(undefined), Math.max(0, deadline - Date.now())); }),
            ]);
            if (status?.ownerEpoch && status.ready !== false)
                return status.ownerEpoch !== disconnectedEpoch;
        }
        catch { }
        finally {
            clearTimeout(timer);
            client.dispose();
        }
        if (!cancelled() && Date.now() < deadline)
            await new Promise(resolve => setTimeout(resolve, Math.min(100, deadline - Date.now())));
    }
    return false;
}
